/// <summary>
/// The <c>AVATonnageContract</c> class is the data contract class for <c>Tonnage</c>
/// </summary>
[
    DataContractAttribute,
    SysOperationContractProcessingAttribute(classStr(AVATonnageUIBuilder)),
    SysOperationGroupAttribute('Parameters', literalStr("@NDX:NXATonnageParameter"), '2')    // , FormArrangeMethod::Vertical),
]
class AVATonnageContract implements SysOperationValidatable,
                                    SysOperationInitializable
{
    Args                                frmArgs;
    KCS_TonnageSetup                    frmKCS_TonnageSetup;

    AVATonnageDaysForwardCalculation    frmAVATonnageDaysForwardCalculation;
    AVATonnagePercentageWarning         frmAVATonnagePercentageWarning;

    boolean                             frmAutomaticMode;
    InventSiteId                        frmInventSiteId;
    StartDate                           frmStartDate;
    EndDate                             frmEndDate;

}

